fn saga_guards(
    resolver: &Resolver<'_>,
    saga: &DomainSaga,
    step: &DomainSagaStep,
    first: bool,
) -> Result<Vec<Expr>, CoreError> {
    let scope = saga_scope(resolver);
    let mut guards = Vec::new();
    if first && let Some(event) = &saga.starts_on {
        resolver.event(event, saga.loc)?;
        guards.push(Expr::Var(event_flag(event)));
    }
    guards.extend(
        step.requires
            .iter()
            .map(|value| resolver.resolve_bool(value, &scope, None))
            .collect::<Result<Vec<_>, _>>()?,
    );
    if step.emits.is_empty() && !step.awaits.is_empty() {
        for event in &step.awaits {
            resolver.event(event, step.loc)?;
        }
        let events = step
            .awaits
            .iter()
            .map(|event| Expr::Var(event_flag(event)))
            .collect::<Vec<_>>();
        guards.push(if step.awaits_mode == "all" {
            and_all(events)
        } else {
            or_all(events)
        });
    }
    Ok(guards)
}

/// The kernel one-hot event-occurrence flag name a domain event lowers to
/// (`event_{event}`). Exported so an external corpus sweep (the #779 saga
/// step/timeout/compensation "evolve pairing" gate) can compute which kernel
/// variable an event's occurrence flag is from the `DomainSpec` alone,
/// rather than pattern-matching generated action bodies for an `event_`
/// prefix — the latter has no `DomainSpec`-side referent to check against.
#[must_use]
pub fn event_flag(event: &str) -> String {
    format!("event_{}", safe(event))
}
